export const CELLS = {
 macro:{name:'巨噬细胞',role:'前排 · 吞噬',detail:'高耐久 · 吸引火力',cost:90,hp:260,damage:23,interval:1.25,range:2.7,speed:2.7,size:1.15,color:'#77d9a4'},
 neutro:{name:'中性粒细胞',role:'突击 · 群体伤害',detail:'快速接敌 · 溅射攻击',cost:60,hp:105,damage:16,interval:.72,range:2.4,speed:4.1,size:.78,color:'#a2d9de'},
 killer:{name:'杀伤 T 细胞',role:'猎手 · 抗病毒',detail:'精准杀伤 · 克制病毒',cost:110,hp:100,damage:27,interval:1,range:7.6,speed:3.3,size:.85,color:'#eebd71'},
 bcell:{name:'B 细胞',role:'远程 · 抗体减速',detail:'远程压制 · 减速目标',cost:100,hp:85,damage:15,interval:1.05,range:10,speed:2.8,size:.85,color:'#a99aeb'},
 helper:{name:'辅助 T 细胞',role:'支援 · 治疗光环',detail:'范围治疗 · 攻击增益',cost:120,hp:110,damage:0,interval:1,range:7,speed:3.1,size:.76,color:'#83dce8'}
};
export const ENEMIES={bacteria:{name:'侵袭细菌',hp:65,damage:9,interval:1.15,range:1.8,speed:1.75,size:.68,reward:6,color:'#e6859a'},virus:{name:'游离病毒',hp:43,damage:6,interval:.8,range:1.6,speed:2.5,size:.62,reward:5,color:'#cc74b6'},armored:{name:'感染宿主',hp:220,damage:20,interval:1.5,range:3.1,speed:1.15,size:1.25,reward:17,color:'#d98868'},boss:{name:'超级病原体',hp:2400,damage:37,interval:1.7,range:4,speed:.8,size:2.7,reward:150,color:'#eb627f'}};
export const ABILITIES={heal:{name:'修复脉冲',key:'Q',cost:60,cooldown:28,radius:7,color:'#78e7ae',icon:'✚',detail:'回复 90 生命 · 28 秒冷却'},blast:{name:'炎症爆发',key:'W',cost:80,cooldown:25,radius:6,color:'#edb86a',icon:'✳',detail:'范围 100 伤害 · 25 秒冷却'},interferon:{name:'干扰素场',key:'E',cost:70,cooldown:32,radius:8,color:'#ab9bef',icon:'◎',detail:'减伤减速 50% · 持续 9 秒'}};
export const RESEARCH={membrane:{name:'强化细胞膜',detail:'每级增加 20% 细胞最大生命',base:120},attack:{name:'抗原识别',detail:'每级增加 20% 细胞攻击与治疗',base:140},metabolism:{name:'高效代谢',detail:'每级增加 2 ATP / 秒，人口上限 +4',base:110}};
export const WAVES=[{name:'细菌先锋',types:[8,0,0],gates:[0]}, {name:'病毒突袭',types:[9,6,0],gates:[0]}, {name:'复合感染',types:[11,8,2],gates:[0,1]}, {name:'包膜突破',types:[13,9,3],gates:[1,2]}, {name:'病原扩散',types:[17,12,4],gates:[0,2]}, {name:'免疫风暴',types:[18,16,5],gates:[0,1,2]}, {name:'全面入侵',types:[21,19,6],gates:[0,1,2]}, {name:'超级病原体',types:[18,16,5],gates:[0,1,2],boss:true}];
export const GATES=[{x:-22,z:-14,name:'入侵口 α'},{x:20,z:-12,name:'入侵口 β'},{x:21,z:18,name:'入侵口 γ'}];
export const dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
const clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
export class Game {
 constructor(difficulty='normal',random=Math.random){this.random=random;this.listeners=[];this.reset(difficulty);}
 on(fn){this.listeners.push(fn);return()=>this.listeners=this.listeners.filter(x=>x!==fn)}
 emit(type,data={}){for(const fn of this.listeners)fn({type,...data})}
 reset(difficulty='normal'){
  this.difficulty=['easy','normal','hard'].includes(difficulty)?difficulty:'normal';this.factor={easy:.72,normal:1,hard:1.35}[this.difficulty];this.nextId=1;this.time=0;this.atp=340;this.wave=0;this.kills=0;this.lost=0;this.phase='prepare';this.units=[];this.enemies=[];this.queue=[];this.spawnQueue=[];this.spawnTimer=0;this.breakTimer=0;this.zones=[];this.research={membrane:0,attack:0,metabolism:0};this.cooldowns={heal:0,blast:0,interferon:0};this.core={id:0,x:-3,z:3,hp:1500,maxHp:1500,size:3.1,team:'core'};this.nodes=[{x:-12,z:-7,name:'营养节点 A',owner:false,progress:0},{x:11,z:5,name:'营养节点 B',owner:false,progress:0},{x:3,z:-15,name:'营养节点 C',owner:false,progress:0}];
  [['macro',-7,1],['macro',-1,-1],['neutro',-8,4],['neutro',0,6],['neutro',-4,-2],['bcell',-6,7],['helper',-3,8]].forEach(([t,x,z])=>this.spawnUnit(t,x,z));this.emit('reset');
 }
 get capacity(){return 30+this.research.metabolism*4}
 get income(){return 3+this.nodes.filter(n=>n.owner).length*3+this.research.metabolism*2}
 get running(){return this.phase==='battle'||this.phase==='break'}
 spawnUnit(type,x,z){const s=CELLS[type],hp=s.hp*(1+this.research.membrane*.2);const u={id:this.nextId++,type,team:'ally',x,z,hp,maxHp:hp,...s,hp,maxHp:hp,cooldown:0,slow:0,order:null,hold:false,seed:this.random()*20};this.units.push(u);this.emit('spawn',{unit:u});return u}
 recruit(type){if(!CELLS[type])return{ok:false,message:'未知细胞类型'};if(['won','lost'].includes(this.phase))return{ok:false,message:'本局已结束，请重新出征'};if(this.units.length+this.queue.length>=this.capacity)return{ok:false,message:'细胞人口已满，可研究高效代谢'};if(this.atp<CELLS[type].cost)return{ok:false,message:'ATP 不足，占领节点可提高收入'};this.atp-=CELLS[type].cost;this.queue.push({type,remaining:2.5});this.emit('recruit',{cellType:type});return{ok:true,message:`${CELLS[type].name} 正在分化`}}
 upgrade(type){const r=RESEARCH[type];if(!r)return{ok:false,message:'未知研究'};if(['won','lost'].includes(this.phase))return{ok:false,message:'本局已结束'};const level=this.research[type],cost=r.base+level*90;if(level>=3)return{ok:false,message:'研究已达到最高等级'};if(this.atp<cost)return{ok:false,message:'ATP 不足'};this.atp-=cost;this.research[type]++;if(type==='membrane')for(const u of this.units){const inc=CELLS[u.type].hp*.2;u.maxHp+=inc;u.hp+=inc;}this.emit('upgrade',{researchType:type});return{ok:true,message:`${r.name} 已提升至 ${level+1} 级`}}
 startWave(){if(!['prepare','break'].includes(this.phase))return{ok:false,message:'请先清除当前波病原体'};if(this.wave>=8)return{ok:false,message:'战役已结束'};this.wave++;this.phase='battle';this.breakTimer=0;const w=WAVES[this.wave-1];this.spawnQueue=[];w.types.forEach((n,i)=>{for(let j=0;j<n;j++)this.spawnQueue.push({type:['bacteria','virus','armored'][i],gate:w.gates[j%w.gates.length]})});for(let i=this.spawnQueue.length-1;i>0;i--){const j=Math.floor(this.random()*(i+1));[this.spawnQueue[i],this.spawnQueue[j]]=[this.spawnQueue[j],this.spawnQueue[i]]}if(w.boss)this.spawnQueue.unshift({type:'boss',gate:1});this.spawnTimer=3.5;this.emit('wave',{wave:this.wave,name:w.name,gates:w.gates});return{ok:true,message:`第 ${this.wave} 波：${w.name}`}}
 spawnEnemy(type,gate){const s=ENEMIES[type],g=GATES[gate],hp=s.hp*this.factor*(1+Math.max(0,this.wave-3)*.04);const e={...s,id:this.nextId++,type,team:'enemy',x:g.x+(this.random()-.5)*3,z:g.z+(this.random()-.5)*3,hp,maxHp:hp,damage:s.damage*this.factor,cooldown:1,slow:0,seed:this.random()*20,bossTimer:9,telegraph:0};this.enemies.push(e);this.emit('spawn',{unit:e});return e}
 command(ids,target){if(!Array.isArray(ids)||!target||!Number.isFinite(target.x)||!Number.isFinite(target.z))return{ok:false,message:'无效指令'};const selected=this.units.filter(u=>ids.includes(u.id));if(!selected.length)return{ok:false,message:'请先选择细胞'};const cols=Math.ceil(Math.sqrt(selected.length));selected.forEach((u,i)=>{u.hold=false;u.order={x:clamp(target.x+(i%cols-(cols-1)/2)*1.7,-24,24),z:clamp(target.z+(Math.floor(i/cols)-(Math.ceil(selected.length/cols)-1)/2)*1.7,-24,24),targetId:target.targetId||null}});this.emit('command',{x:target.x,z:target.z});return{ok:true,message:target.targetId?'集中攻击目标':'移动指令已下达'}}
 hold(ids){this.units.filter(u=>ids.includes(u.id)).forEach(u=>{u.order=null;u.hold=true});return{ok:true,message:'编队原地驻守'}}
 cast(type,p){const a=ABILITIES[type];if(!a||!p||!Number.isFinite(p.x)||!Number.isFinite(p.z))return{ok:false,message:'无效技能目标'};if(['won','lost'].includes(this.phase))return{ok:false,message:'本局已结束'};if(this.cooldowns[type]>.01)return{ok:false,message:'技能正在冷却'};if(this.atp<a.cost)return{ok:false,message:'ATP 不足'};this.atp-=a.cost;this.cooldowns[type]=a.cooldown;const pos={x:clamp(p.x,-27,27),z:clamp(p.z,-27,27)};
  if(type==='heal'){for(const u of this.units)if(dist(u,pos)<a.radius)u.hp=Math.min(u.maxHp,u.hp+90);if(dist(this.core,pos)<a.radius)this.core.hp=Math.min(this.core.maxHp,this.core.hp+100)}
  if(type==='blast')for(const e of this.enemies)if(dist(e,pos)<a.radius){this.damage(e,100, null);e.slow=4}
  if(type==='interferon')this.zones.push({...pos,type,remaining:9,radius:a.radius});this.emit('ability',{abilityType:type,...pos,radius:a.radius});this.cleanup();return{ok:true,message:`${a.name} 已释放`}}
 damage(target,amount,source){if(target.hp<=0)return;let actual=amount;if(target.type==='armored'&&source?.type!=='killer')actual*=.75;target.hp=Math.max(0,target.hp-actual);if(source)this.emit('attack',{from:source,to:target,damage:actual});}
 move(u,p,dt,mult=1){const d=dist(u,p);if(d<.08)return;const step=Math.min(d,u.speed*dt*mult);u.x+=(p.x-u.x)/d*step;u.z+=(p.z-u.z)/d*step;u.x=clamp(u.x,-27,27);u.z=clamp(u.z,-27,27)}
 cleanup(){for(const e of this.enemies.filter(e=>e.hp<=0)){this.atp+=e.reward;this.kills++;this.emit('death',{unit:e})}for(const u of this.units.filter(u=>u.hp<=0)){this.lost++;this.emit('death',{unit:u})}this.enemies=this.enemies.filter(e=>e.hp>0);this.units=this.units.filter(u=>u.hp>0);}
 tick(dt){if(!Number.isFinite(dt)||dt<=0||['won','lost'].includes(this.phase))return;dt=Math.min(dt,.1);if(this.running){this.time+=dt;this.atp=Math.min(9999,this.atp+this.income*dt)}
  for(const k of Object.keys(this.cooldowns))this.cooldowns[k]=Math.max(0,this.cooldowns[k]-dt);
  if(this.queue.length){this.queue[0].remaining-=dt;if(this.queue[0].remaining<=0){const q=this.queue.shift(),ang=this.random()*Math.PI*2;this.spawnUnit(q.type,this.core.x+Math.cos(ang)*5,this.core.z+Math.sin(ang)*5)}}
  for(const node of this.nodes){const ally=this.units.some(u=>dist(u,node)<3.8),enemy=this.enemies.some(e=>dist(e,node)<3.8);if(ally&&!enemy){node.progress=Math.min(6,node.progress+dt);if(node.progress>=6&&!node.owner){node.owner=true;this.emit('capture',{node})}}else if(enemy&&!ally){node.progress=Math.max(0,node.progress-dt*1.5);if(node.owner&&node.progress===0){node.owner=false;this.emit('nodeLost',{node})}}else if(!node.owner&&!ally)node.progress=Math.max(0,node.progress-dt*.2)}
  if(this.phase==='break'){this.breakTimer-=dt;if(this.breakTimer<=0)this.startWave()}
  if(this.phase==='battle'&&this.spawnQueue.length){this.spawnTimer-=dt;if(this.spawnTimer<=0){const item=this.spawnQueue.shift();this.spawnEnemy(item.type,item.gate);this.spawnTimer=item.type==='boss'?5:.85}}
  this.zones.forEach(z=>z.remaining-=dt);this.zones=this.zones.filter(z=>z.remaining>0);
  for(const u of this.units)u.healLock=Math.max(0,(u.healLock||0)-dt);
  for(const u of this.units){if(u.hp<=0)continue;u.cooldown-=dt;let nearest=null,min=Infinity;const targetOrder=u.order?.targetId?this.enemies.find(e=>e.id===u.order.targetId&&e.hp>0):null;
   if(u.order?.targetId&&!targetOrder)u.order=null;
   if(u.type==='helper'&&u.cooldown<=0){let healed=false;for(const other of this.units)if(other.hp>0&&dist(u,other)<7&&other.hp<other.maxHp&&!other.healLock){other.healLock=1;other.hp=Math.min(other.maxHp,other.hp+9*(1+this.research.attack*.2));healed=true}if(healed)this.emit('heal',{unit:u});u.cooldown=1}
   if(u.order&&!u.order.targetId){this.move(u,u.order,dt);if(dist(u,u.order)<.2)u.order=null;continue}
   if(targetOrder){nearest=targetOrder;min=dist(u,targetOrder)}else for(const e of this.enemies){const d=dist(u,e);if(e.hp>0&&d<min){min=d;nearest=e}}
   if(u.type==='helper'&&targetOrder&&dist(u,targetOrder)>5.8)this.move(u,targetOrder,dt);
   if(u.type!=='helper'&&nearest){if(min<=u.range+nearest.size*.3){if(u.cooldown<=0){let damage=u.damage*(1+this.research.attack*.2);if(this.units.some(a=>a.type==='helper'&&a.hp>0&&dist(u,a)<7))damage*=1.15;if(u.type==='killer'&&nearest.type==='virus')damage*=1.8;this.damage(nearest,damage,u);if(u.type==='bcell')nearest.slow=2.5;if(u.type==='neutro')for(const e of this.enemies)if(e!==nearest&&e.hp>0&&dist(e,nearest)<2.5)this.damage(e,damage*.45);u.cooldown=u.interval;}}
    else if(!u.hold&&(targetOrder||min<12))this.move(u,nearest,dt);
   }else if(u.type==='helper'&&!u.hold&&!u.order){const hurt=this.units.filter(a=>a.hp>0&&a.hp<a.maxHp*.85).sort((a,b)=>dist(a,u)-dist(b,u))[0];if(hurt&&dist(u,hurt)>5&&dist(u,hurt)<15)this.move(u,hurt,dt)}
   if(this.phase!=='battle')u.hp=Math.min(u.maxHp,u.hp+dt*2);
  }
  for(const e of this.enemies){if(e.hp<=0)continue;e.cooldown-=dt;e.slow=Math.max(0,e.slow-dt);const suppressed=this.zones.some(z=>dist(e,z)<z.radius);let target=this.core,min=dist(e,this.core)-2;
   for(const u of this.units){if(u.hp<=0)continue;const d=dist(e,u);const aggro=u.type==='macro'?9:6;if(d<aggro&&d<(min+(u.type==='macro'?2:0))){target=u;min=d}}
   const actualDist=dist(e,target),reach=e.range+(target.team==='core'?2.4:target.size*.4);if(actualDist>reach)this.move(e,target,dt,(e.slow>0?.55:1)*(suppressed?.5:1));else if(e.cooldown<=0){this.damage(target,e.damage*(suppressed?.5:1),e);e.cooldown=e.interval}
   if(e.type==='boss'){e.bossTimer-=dt;if(e.bossTimer<=0&&e.telegraph<=0){e.telegraph=1.7;e.bossTimer=11;this.emit('bossWarning',{unit:e})}if(e.telegraph>0){e.telegraph-=dt;if(e.telegraph<=0){for(const u of this.units)if(dist(u,e)<7)this.damage(u,45*this.factor*(suppressed?.5:1));if(dist(this.core,e)<9)this.damage(this.core,55*this.factor*(suppressed?.5:1));this.emit('bossPulse',{unit:e})}}}
  }
  // Local separation keeps formations legible without overriding movement orders.
  const living=[...this.units,...this.enemies];for(let i=0;i<living.length;i++)for(let j=i+1;j<living.length;j++){const a=living[i],b=living[j],d=dist(a,b),spacing=(a.size+b.size)*.7;if(d<spacing){const dx=d>.001?(a.x-b.x)/d:1,dz=d>.001?(a.z-b.z)/d:0,push=(spacing-d)*Math.min(.5,dt*3);a.x+=dx*push;a.z+=dz*push;b.x-=dx*push;b.z-=dz*push}}
  this.cleanup();if(this.core.hp<=0){this.phase='lost';this.emit('end',{won:false});return}if(this.phase==='battle'&&!this.spawnQueue.length&&!this.enemies.length){if(this.wave===8){this.phase='won';this.emit('end',{won:true})}else{this.phase='break';this.breakTimer=20;const reward=70+this.wave*10;this.atp+=reward;this.emit('waveClear',{wave:this.wave,reward})}}
 }
 snapshot(){return{phase:this.phase,wave:this.wave,time:Math.round(this.time),atp:Math.floor(this.atp),income:this.income,coreHealth:Math.round(this.core.hp),coreMaxHealth:this.core.maxHp,units:this.units.map(u=>({id:u.id,type:u.type,x:Math.round(u.x*10)/10,z:Math.round(u.z*10)/10,hp:Math.ceil(u.hp)})),enemyCount:this.enemies.length,pendingEnemies:this.spawnQueue.length,queue:this.queue.map(q=>q.type),research:{...this.research},kills:this.kills,nodes:this.nodes.map(n=>({name:n.name,owned:n.owner,progress:Math.round(n.progress*100/6)}))}}
}
